<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Booking confirmed</title><style>body{font-family:system-ui,sans-serif;background:#f5f5f2;color:#17211b}main{max-width:760px;margin:auto;padding:40px 20px}.card{background:#fff;border:1px solid #cad5ce;border-radius:14px;padding:24px}code{word-break:break-all}</style></head><body><main><div class="card"><h1>Booking confirmed</h1><p>Your verified 5% deposit has been recorded. This booking is now confirmed.</p><p>Deposit: <strong>{{ number_format($confirmation['depositMinor']) }} PKR minor units</strong></p><p>Confirmation reference: <code>{{ $confirmation['confirmationId'] }}</code></p><p>Keep your status token: <code>{{ $confirmation['token'] }}</code></p><p><a href="/book/status?token={{ $confirmation['token'] }}">View booking status</a></p></div></main></body></html>